{
  "category_edits": [
    {
      "category": "interest_aggregation",
      "rationale": "Blend each causal encoder state with a normalized recency-weighted mean of valid states through that position: 0.8*h_t + 0.2*m_t, with a five-item half-life. This may stabilize recent interests across all four datasets while preserving the backbone, scoring, loss, optimizer, seeds and epoch cap. The generated predictor imports the same updated model class.",
      "edits": [
        {
          "find": "        return self.last_layernorm(seq_emb)\n",
          "replace": "        states = self.last_layernorm(seq_emb)\n        valid = (~timeline_mask).to(dtype=states.dtype)\n        positions = torch.arange(M, device=seq.device)\n        distance = positions.unsqueeze(1) - positions.unsqueeze(0)\n        causal_weights = torch.exp(\n            -math.log(2.0) * distance.clamp_min(0).to(states.dtype) / 5.0\n        ) * distance.ge(0).to(states.dtype)\n        weights = causal_weights.unsqueeze(0) * valid.unsqueeze(1)\n        weights = weights / weights.sum(dim=-1, keepdim=True).clamp_min(1e-8)\n        pooled = torch.bmm(weights, states * valid.unsqueeze(-1))\n        return (0.8 * states + 0.2 * pooled) * valid.unsqueeze(-1)\n"
        },
        {
          "find": "            \"input_feature\": \"causal_prefix_repeat_v1\",\n",
          "replace": "            \"input_feature\": \"causal_prefix_repeat_v1\",\n            \"interest_aggregation\": \"causal_recency_half_life_5_blend_0.2_v1\",\n"
        },
        {
          "find": "        # The imported SASRec computes causal prefix-repeat scaling in log2feats.\n",
          "replace": "        if meta.get(\"interest_aggregation\") != \"causal_recency_half_life_5_blend_0.2_v1\":\n            raise ValueError(f\"Unexpected interest aggregation configuration for {ds}\")\n        # The imported SASRec applies the same causal recency readout as training.\n"
        }
      ]
    }
  ],
  "change_summary": "Apply causal recency pooling at every training and inference position, excluding padding and future states. Preserve one trained checkpoint per category and validate readout metadata in the predictor writer."
}
